import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Lesson 15: Course Review & Learning Path","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-6/lesson-15.md","filePath":"en/modules/module-6/lesson-15.md"}'),i={name:"en/modules/module-6/lesson-15.md"};function s(n,e,d,l,u,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="lesson-15-course-review-learning-path" tabindex="-1">Lesson 15: Course Review &amp; Learning Path <a class="header-anchor" href="#lesson-15-course-review-learning-path" aria-label="Permalink to &quot;Lesson 15: Course Review &amp; Learning Path&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Review core knowledge points and master common troubleshooting methods ⏱️ <strong>Estimated Time</strong>: 15 minutes 🎯 <strong>Teaching Rhythm</strong>: Summary review + troubleshooting</p></blockquote><hr><h2 id="i-core-knowledge-review" tabindex="-1">I. Core Knowledge Review <a class="header-anchor" href="#i-core-knowledge-review" aria-label="Permalink to &quot;I. Core Knowledge Review&quot;">​</a></h2><h3 id="module-1-understanding-codex" tabindex="-1">Module 1: Understanding Codex <a class="header-anchor" href="#module-1-understanding-codex" aria-label="Permalink to &quot;Module 1: Understanding Codex&quot;">​</a></h3><ul><li>Codex is OpenAI&#39;s AI programming agent. It can read files, write code, and run commands.</li><li>It is not a chat tool, nor a simple code completion tool.</li><li>Analogy: Codex = a programming-savvy intern.</li></ul><h3 id="module-2-getting-started" tabindex="-1">Module 2: Getting Started <a class="header-anchor" href="#module-2-getting-started" aria-label="Permalink to &quot;Module 2: Getting Started&quot;">​</a></h3><ul><li>You need a ChatGPT account (Plus/Pro recommended).</li><li>The desktop app is the most beginner-friendly entry point.</li><li>Core concepts: Workspace and Permission modes.</li></ul><h3 id="module-3-core-features" tabindex="-1">Module 3: Core Features <a class="header-anchor" href="#module-3-core-features" aria-label="Permalink to &quot;Module 3: Core Features&quot;">​</a></h3><ul><li><strong>File Operations</strong>: Read, edit, organize, and batch process files.</li><li><strong>Natural Language Driven</strong>: Command AI by talking.</li><li><strong>Web Search</strong>: Search + organize + summarize.</li><li><strong>Automation</strong>: Batch rename, download &amp; organize, write scripts.</li></ul><h3 id="module-4-practical-tips" tabindex="-1">Module 4: Practical Tips <a class="header-anchor" href="#module-4-practical-tips" aria-label="Permalink to &quot;Module 4: Practical Tips&quot;">​</a></h3><ul><li><strong>Write Better Prompts</strong>: Four elements — action + object + rules + acceptance criteria.</li><li><strong>Use Safely</strong>: Back up important files, limit workspace.</li><li><strong>Call Skills</strong>: PPT generation, web development, and other preset templates.</li></ul><h3 id="module-5-project-practice" tabindex="-1">Module 5: Project Practice <a class="header-anchor" href="#module-5-project-practice" aria-label="Permalink to &quot;Module 5: Project Practice&quot;">​</a></h3><ul><li>Project 1: Organize your computer folder</li><li>Project 2: Create a PPT report</li><li>Project 3: Build a personal profile webpage</li><li>Project 4: Todo List App</li></ul><hr><h2 id="ii-common-troubleshooting" tabindex="-1">II. Common Troubleshooting <a class="header-anchor" href="#ii-common-troubleshooting" aria-label="Permalink to &quot;II. Common Troubleshooting&quot;">​</a></h2><h3 id="issue-1-login-failure" tabindex="-1">Issue 1: Login Failure <a class="header-anchor" href="#issue-1-login-failure" aria-label="Permalink to &quot;Issue 1: Login Failure&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Possible Cause</th><th>Solution</th></tr></thead><tbody><tr><td>Unstable network</td><td>Check your connection, try switching networks</td></tr><tr><td>Account not activated</td><td>Confirm your email has been verified</td></tr><tr><td>Regional restrictions</td><td>Check whether your region supports Codex</td></tr></tbody></table><h3 id="issue-2-permission-problems" tabindex="-1">Issue 2: Permission Problems <a class="header-anchor" href="#issue-2-permission-problems" aria-label="Permalink to &quot;Issue 2: Permission Problems&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Solution</th></tr></thead><tbody><tr><td>Codex can&#39;t access a folder</td><td>Check whether the workspace setting is correct</td></tr><tr><td>Operation denied</td><td>Check the permission mode setting</td></tr><tr><td>File can&#39;t be saved</td><td>Confirm the folder has write permission</td></tr></tbody></table><h3 id="issue-3-task-stuck" tabindex="-1">Issue 3: Task Stuck <a class="header-anchor" href="#issue-3-task-stuck" aria-label="Permalink to &quot;Issue 3: Task Stuck&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Solution</th></tr></thead><tbody><tr><td>Codex unresponsive for a long time</td><td>Refresh the page or restart the app</td></tr><tr><td>Output doesn&#39;t match expectations</td><td>Rephrase your request more specifically</td></tr><tr><td>Error message unintelligible</td><td>Copy the error message to Codex and ask it to explain</td></tr></tbody></table><h3 id="issue-4-quota-exhausted" tabindex="-1">Issue 4: Quota Exhausted <a class="header-anchor" href="#issue-4-quota-exhausted" aria-label="Permalink to &quot;Issue 4: Quota Exhausted&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Solution</th></tr></thead><tbody><tr><td>Prompt says quota is used up</td><td>Upgrade to Plus or Pro</td></tr><tr><td>Free quota not enough</td><td>Wait for monthly reset or use alternative tools</td></tr></tbody></table><hr><h2 id="iii-recommended-learning-resources" tabindex="-1">III. Recommended Learning Resources <a class="header-anchor" href="#iii-recommended-learning-resources" aria-label="Permalink to &quot;III. Recommended Learning Resources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource Type</th><th>Link / Name</th><th>Description</th></tr></thead><tbody><tr><td>Official docs</td><td>chatgpt.com/docs</td><td>OpenAI official documentation</td></tr><tr><td>Community forum</td><td>community.openai.com</td><td>User discussions and experience sharing</td></tr><tr><td>YouTube tutorials</td><td>Search &quot;Codex tutorial&quot;</td><td>Video tutorials</td></tr><tr><td>Reddit communities</td><td>r/Claude, r/OpenAI</td><td>Discussions on latest developments</td></tr></tbody></table><hr><h2 id="iv-summary" tabindex="-1">IV. Summary <a class="header-anchor" href="#iv-summary" aria-label="Permalink to &quot;IV. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Knowledge Point</th><th>Core Content</th></tr></thead><tbody><tr><td>Knowledge review</td><td>Complete learning path from installation to practice</td></tr><tr><td>Troubleshooting</td><td>Login, permission, stuck tasks, quota issues</td></tr><tr><td>Learning resources</td><td>Official docs, communities, video tutorials</td></tr></tbody></table><hr><h2 id="v-next-step" tabindex="-1">V. Next Step <a class="header-anchor" href="#v-next-step" aria-label="Permalink to &quot;V. Next Step&quot;">​</a></h2><p><a href="./lesson-16.html">→ Lesson 16: What to Learn Next</a></p>',33)])])}const p=t(i,[["render",s]]);export{m as __pageData,p as default};
